const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const followup_token = text(input.followup_token);
const mobile = text(input.mobile);
const recovery_status = text(input.recovery_status).toLowerCase();
const pain_level = Number(input.pain_level);
const has_red_flag = toBoolean(input.has_red_flag);
const red_flag_details = text(input.red_flag_details);
const has_medication_issue = toBoolean(input.has_medication_issue);
const medication_issue_details = text(input.medication_issue_details);
const has_complaint = toBoolean(input.has_complaint);
const complaint_details = text(input.complaint_details);
const satisfaction_score = Number(input.satisfaction_score);
const patient_comment = text(input.patient_comment);
const confirm_response = toBoolean(input.confirm_response);

const errors = [];

if (!followup_token) {
  errors.push({
    field: 'followup_token',
    message: 'توکن پیگیری الزامی است.',
  });
}

if (!mobile) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل بیمار الزامی است.',
  });
}

if (mobile && !/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (!['better', 'same', 'worse'].includes(recovery_status)) {
  errors.push({
    field: 'recovery_status',
    message: 'وضعیت بهبود باید better، same یا worse باشد.',
  });
}

if (!Number.isInteger(pain_level) || pain_level < 0 || pain_level > 10) {
  errors.push({
    field: 'pain_level',
    message: 'شدت درد باید یک عدد صحیح بین 0 و 10 باشد.',
  });
}

if (has_red_flag && !red_flag_details) {
  errors.push({
    field: 'red_flag_details',
    message: 'در صورت وجود علامت هشدار، توضیح آن الزامی است.',
  });
}

if (has_medication_issue && !medication_issue_details) {
  errors.push({
    field: 'medication_issue_details',
    message: 'در صورت وجود مشکل دارویی، توضیح آن الزامی است.',
  });
}

if (has_complaint && !complaint_details) {
  errors.push({
    field: 'complaint_details',
    message: 'در صورت ثبت شکایت، توضیح آن الزامی است.',
  });
}

if (
  !Number.isInteger(satisfaction_score) ||
  satisfaction_score < 1 ||
  satisfaction_score > 5
) {
  errors.push({
    field: 'satisfaction_score',
    message: 'امتیاز رضایت باید یک عدد صحیح بین 1 و 5 باشد.',
  });
}

for (const [field, value, max] of [
  ['red_flag_details', red_flag_details, 1000],
  ['medication_issue_details', medication_issue_details, 1000],
  ['complaint_details', complaint_details, 1000],
  ['patient_comment', patient_comment, 2000],
]) {
  if (value.length > max) {
    errors.push({
      field,
      message: `طول ${field} بیشتر از حد مجاز است.`,
    });
  }
}

if (confirm_response !== true) {
  errors.push({
    field: 'confirm_response',
    message: 'پاسخ بیمار باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    followup_token,
    mobile,
    recovery_status,
    pain_level,
    has_red_flag,
    red_flag_details,
    has_medication_issue,
    medication_issue_details,
    has_complaint,
    complaint_details,
    satisfaction_score,
    patient_comment,
    confirm_response,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات پاسخ پیگیری ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];
